export async function fillSignInForm(page: Page, username: string, password: string) {
    await page.getByTestId("username-input").fill(username);
    await page.getByTestId("password-input").fill(password);
}

export async function submitSignInForm(page: Page) {
    await page.getByTestId("submit-login-button").click();
    await page.waitForURL((u: URL) => !u.pathname.startsWith('/login'));
}
